const item = $input.first();
const message = item.json.body ?? item.json;
const files = Object.entries(item.binary ?? {});
const result = { chatInput: message.chatInput, sessionId: message.formSessionId ?? message.sessionId ?? '', attachmentStatus: 'none', fileName: '', content: '' };
if (files.length > 1) {
  result.attachmentStatus = 'multiple';
} else if (files.length === 1) {
  const [key, file] = files[0];
  result.fileName = file.fileName ?? '';
  if (/\.(docx|pdf)$/i.test(result.fileName)) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    result.content = buffer.toString('base64');
    result.attachmentStatus = 'supported';
  } else {
    result.attachmentStatus = 'unsupported';
  }
}
return [{ json: result }];

const items = $input.all();
const bareReportUrl = /(?<!\(|\[|<)http:\/\/localhost:8765\/reviews\/[a-f0-9]{32}\b/gi;
const lookup = $('Найти отчёт по сессии');
const current = lookup.isExecuted ? lookup.first().json : null;
const statusMessage = {
  missing: 'В этом чате пока нет проверки. Загрузите договор в формате DOCX или текстового PDF.',
  queued: 'Договор принят и ожидает проверки.',
  running: 'Договор проверяется.',
  failed: 'Проверка завершилась ошибкой. Загрузите договор ещё раз.',
};
for (const item of items) {
  if (current?.state === 'template_mismatch') {
    const fit = current.template_fit;
    item.json.output = 'Нужно проверить шаблон. Найдено близких пар: ' + fit.matched_pairs + ' из ' +
      fit.template_count + ' пунктов шаблона и ' + fit.matched_pairs + ' из ' + fit.carrier_count +
      ' пунктов договора.\n\n[Посмотреть диагностику](' + current.redirect + ')';
  }
  if (current && statusMessage[current.state]) item.json.output = statusMessage[current.state];
  if (current?.state === 'completed' && typeof item.json.output === 'string' && !item.json.output.includes(current.redirect)) {
    item.json.output += '\n\n[Открыть отчёт](' + current.redirect + ')';
  }
  if (typeof item.json.output === 'string') {
    item.json.output = item.json.output.replace(bareReportUrl, url => '[Открыть отчёт](' + url + ')');
  }
}
const sessionId = $('Получить запрос').first().json.formSessionId;
if (sessionId) {
  for (const item of items) {
    item.json.formSubmission = true;
    const steps = item.json.intermediateSteps ?? [];
    for (const step of steps) {
      if (step.action?.tool !== 'check_uploaded_contract') continue;
      try {
        const result = JSON.parse(step.observation);
        const observation = Array.isArray(result) ? result[0] : result;
        if (typeof observation?.detail === 'string') item.json.formError = observation.detail;
        const reviewId = observation?.id;
        if (/^[a-f0-9]{32}$/.test(reviewId ?? '')) {
          const query = 'session=' + encodeURIComponent(sessionId) + '&review=' + reviewId;
          item.json.formRedirect = 'http://localhost:8765/review#' + query;
          break;
        }
      } catch {
        // A tool error can return text rather than a review record.
      }
    }
  }
}
return items;
